import heapq


class StablePriorityQueue:
    def __init__(self):
        self._heap = []
        self._counter = 0

    def push(self, priority, item):
        heapq.heappush(self._heap, (priority, self._counter, item))
        self._counter -= 1

    def pop(self):
        priority, order, item = heapq.heappop(self._heap)
        return item

    def __len__(self):
        return len(self._heap)
